ruleContent.content:
#booktxt@html
@js:
var s = String(result||'');
var out = '';
var re = /bb\('([A-Za-z0-9+/=]+)'\)/g;
var m;
while ((m = re.exec(s)) !== null) { out += String(java.base64Decode(m[1])); }
if (out === '') { out = s; }
out = out.replace(/<p[^>]*>\s*(请勿开启浏览器阅读模式|相邻推荐)[\s\S]*$/, '');
out = out.replace(/<a[^>]*href="\/ibqg\/[\s\S]*$/, '');
out;

ruleToc.nextTocUrl:
@js:
var list = [];
var u = String(baseUrl);
if (!/ml\d+\.html$/.test(u)) {
  try {
    var book = u.replace(/ml\d+\.html$/, '');
    var h = String(java.ajax(book + 'ml1.html'));
    var re = /<option[^>]*value="([^"]+)"/g;
    var m;
    while ((m = re.exec(h)) !== null) {
      if (m[1].indexOf('.html') > -1) { list.push(m[1]); }
    }
  } catch (e) {}
}
list;
